CHANGELOG = '\n\n## 2026-11-28, A20 (robustness of the scale-learning planner)\n- Added src/dwell/a20.py, analysis_a20.py, scripts/run_a20.py, analyze_a20.py, a20_gate.py, mutate_a20.py, configs a20_main and a20_audit, tests/test_a20.py, append_a20_plan.py. Plan e1ec0e0, code and gate 786d520.\n- Outcome ROBUST-LEARNER / LEARNING-NEEDED (main run, 11520 rows). docs/analysis_plan_P0.md and docs/record.md: A20 outcome.\n'

TARGETS = [("docs/analysis_plan_P0.md", PLAN, "#### A20 outcome (2026-11-28): ROBUST-LEARNER / LEARNING-NEEDED"),
           ("docs/record.md", RECORD, "## A20 (2026-11-27 to 2026-11-28)"),
           ("docs/CHANGELOG.md", CHANGELOG, "## 2026-11-28, A20 (robustness of the scale-learning planner)")]


def main():
    plan = []
    for rel, text, marker in TARGETS:
        if not os.path.exists(rel):
            sys.exit(f"ERROR: {rel} not found (run from the repository root)")
        raw = open(rel, "rb").read()
        if marker.encode() in raw:
            sys.exit(f"ERROR: {rel} already contains '{marker}'; nothing written")
        if not raw.endswith(b"\n"):
            sys.exit(f"ERROR: {rel} does not end with a newline; nothing written")
        new = text.replace("\r\n", "\n")
        if b"\r\n" in raw:
            new = new.replace("\n", "\r\n")
        plan.append((rel, raw, new.encode("utf-8")))
    for rel, raw, add in plan:
        open(rel, "wb").write(raw + add)
        print("appended", rel, f"(+{len(add)} bytes)")


if __name__ == "__main__":
    main()
